-- 21/11: a supplier has no code of its own any more. The code was generated by the system, so it only repeated the
-- id; suppliers are identified by id and by their name, unique ignoring case (ux_supplier_name_ci, kept).
-- Dropping the column also drops its UNIQUE constraint. The old codes are not kept.
ALTER TABLE supplier DROP COLUMN supplier_code;
DROP SEQUENCE supplier_code_seq;
